mapper.select:

WHERE p.id = #{postingId}
    AND p.deleted = FALSE

    AND FALSE


        AND c.seller_id IN

            #{sellerId}



    p.deleted = FALSE
        AND p.document_date >= #{timeRange.startDate}
        AND p.document_date <= #{timeRange.endDate}

        AND FALSE


            AND c.seller_id IN

                #{sellerId}



    AND p.id = #{query.postingId}
    AND p.customer_id = #{query.customerId}

        AND (p.posting_no ILIKE CONCAT('%', #{query.keyword}, '%')
            OR p.customer_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))


        AND p.refund_status = #{query.refundStatus}

    AND v.id IS NULL
    AND v.id IS NOT NULL

ORDER BY p.document_date DESC, p.id DESC
